import 'package:eduflow_core/eduflow_core.dart';
import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:go_router/go_router.dart';

final facultyLeavesProvider = FutureProvider<List<Map<String, dynamic>>>((ref) async {
  final response = await ref.watch(dioClientProvider).dio.get('/faculty/me/leave-requests');
  final body = Map<String, dynamic>.from(response.data as Map);
  return (body['data'] as List? ?? const []).whereType<Map>().map((row) => Map<String, dynamic>.from(row)).toList();
});

class FacultyLeaveScreen extends ConsumerStatefulWidget { const FacultyLeaveScreen({super.key}); @override ConsumerState<FacultyLeaveScreen> createState() => _FacultyLeaveScreenState(); }
