  @override Widget build(BuildContext context) { final state = ref.watch(facultyLeavesProvider); return Scaffold(appBar: AppBar(title: const Text('Faculty leave'), leading: IconButton(onPressed: () => context.go('/faculty'), icon: const Icon(Icons.arrow_back_rounded))), body: ListView(padding: const EdgeInsets.all(16), children: [Container(padding: const EdgeInsets.all(20), decoration: BoxDecoration(borderRadius: BorderRadius.circular(26), gradient: const LinearGradient(colors: [Color(0xFF1C255D), Color(0xFF614FEF)])), child: const Column(crossAxisAlignment: CrossAxisAlignment.start, children: [Text('TEACHING CONTINUITY', style: TextStyle(color: Color(0xFFBFEFFD), fontWeight: FontWeight.w800)), SizedBox(height: 8), Text('Request leave with a clear handover.', style: TextStyle(color: Colors.white, fontSize: 20, fontWeight: FontWeight.w800))])), const SizedBox(height: 18), Card(child: Padding(padding: const EdgeInsets.all(16), child: Column(children: [Row(children: [Expanded(child: OutlinedButton(onPressed: () => _pick(true), child: Text('From: ${_date(_from)}'))), const SizedBox(width: 10), Expanded(child: OutlinedButton(onPressed: () => _pick(false), child: Text('To: ${_date(_to)}')))]), const SizedBox(height: 12), TextField(controller: _reason, maxLines: 3, decoration: const InputDecoration(labelText: 'Reason')), const SizedBox(height: 12), TextField(controller: _handover, maxLines: 2, decoration: const InputDecoration(labelText: 'Handover note (optional)')), const SizedBox(height: 16), SizedBox(width: double.infinity, child: FilledButton.icon(onPressed: _saving ? null : _submit, icon: _saving ? const SizedBox.square(dimension: 18, child: CircularProgressIndicator(strokeWidth: 2)) : const Icon(Icons.send_rounded), label: const Text('Submit leave request')))]))), const SizedBox(height: 22), Text('My requests', style: Theme.of(context).textTheme.titleLarge?.copyWith(fontWeight: FontWeight.w800)), const SizedBox(height: 8), state.when(loading: () => const Center(child